import { createHash } from "node:crypto";

/** The only persistent attachment references supported by the runtime. */
export type CheckpointAttachmentKind =
  | "task-attachment"
  | "recovery-instruction"
  | "context"
  | "external-artifact-ref"
  | "ledger-checkpoint";

export const CHECKPOINT_ATTACHMENT_KINDS: readonly CheckpointAttachmentKind[] = [
  "task-attachment",
  "recovery-instruction",
  "context",
  "external-artifact-ref",
  "ledger-checkpoint",
];

export type CheckpointAttachmentBinding = {
  readonly kind: CheckpointAttachmentKind;
  /** Stable reference within the checkpoint, never an arbitrary cursor or blob. */
  readonly attachmentRef: string;
  /** SHA-256 digest of the referenced content. */
  readonly contentHash: string;
  /** Principal allowed to use the binding. */
  readonly owner: string;
  /** Absolute expiry time in Unix epoch milliseconds. */
  readonly ttl: number;
};

export type CheckpointAttachmentRecoveryState =
  | "recovered"
  | "missing-hash"
  | "invalid-hash"
  | "missing-owner"
  | "expired"
  | "conflict"
  | "invalid-kind"
  | "invalid-ref";

export type CheckpointAttachmentRecoveryEntry = {
  readonly kind: CheckpointAttachmentKind | string;
  readonly attachmentRef: string;
  readonly contentHash: string | null;
  readonly owner: string | null;
  readonly ttl: number | null;
  readonly state: CheckpointAttachmentRecoveryState;
  readonly reason: string;
};

export type CheckpointAttachmentRecovery = {
  readonly entries: readonly CheckpointAttachmentRecoveryEntry[];
  readonly recovered: readonly CheckpointAttachmentRecoveryEntry[];
  readonly digest: string;
};

export type RecoverCheckpointAttachmentBindingsOptions = {
  /** Evaluation time in Unix epoch milliseconds. Supplying it makes recovery reproducible. */
  readonly now?: number;
};

const SHA256_HEX = /^[0-9a-f]{64}$/i;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function asNonEmptyString(value: unknown): string | null {
  return typeof value === "string" && value.trim().length > 0 ? value : null;
}

function asTtl(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

function canonicalEntry(entry: CheckpointAttachmentRecoveryEntry): Record<string, unknown> {
  return {
    attachmentRef: entry.attachmentRef,
    contentHash: entry.contentHash,
    kind: entry.kind,
    owner: entry.owner,
    reason: entry.reason,
    state: entry.state,
    ttl: entry.ttl,
  };
}

/**
 * Compute the stable digest of a recovery result. The digest intentionally
 * covers the rejected entries as well as the recovered entries.
 */
export function computeCheckpointAttachmentRecoveryDigest(
  recovery: Omit<CheckpointAttachmentRecovery, "digest"> | CheckpointAttachmentRecovery,
): string {
  const canonical = JSON.stringify({
    entries: recovery.entries.map(canonicalEntry),
    recovered: recovery.recovered.map(canonicalEntry),
  });
  return createHash("sha256").update(canonical, "utf8").digest("hex");
}

function entryFor(
  binding: CheckpointAttachmentBinding,
  state: CheckpointAttachmentRecoveryState,
  reason: string,
): CheckpointAttachmentRecoveryEntry {
  return {
    kind: binding.kind,
    attachmentRef: binding.attachmentRef,
    contentHash: binding.contentHash || null,
    owner: binding.owner || null,
    ttl: binding.ttl,
    state,
    reason,
  };
}

/**
 * Recover a checkpoint's attachment bindings without mutating its input and
 * without performing I/O or replaying side effects.
 *
 * A reference is retained only when its kind is allow-listed, its SHA-256
 * hash is valid, an owner is present, and its TTL has not elapsed. For a
 * reference seen with more than one hash, the first binding wins and every
 * later conflicting binding is explicitly rejected. Identical ref+hash pairs
 * are de-duplicated.
 */
export function recoverCheckpointAttachmentBindings(
  bindings: readonly CheckpointAttachmentBinding[],
  options: RecoverCheckpointAttachmentBindingsOptions = {},
): CheckpointAttachmentRecovery {
  const now = options.now ?? Date.now();
  const seen = new Map<string, { hash: string; entry: CheckpointAttachmentRecoveryEntry }>();
  const output: CheckpointAttachmentRecoveryEntry[] = [];

  for (const binding of bindings) {
    const ref = asNonEmptyString(binding.attachmentRef);
    const hash = asNonEmptyString(binding.contentHash);
    const owner = asNonEmptyString(binding.owner);
    const ttl = asTtl(binding.ttl);

    if (!CHECKPOINT_ATTACHMENT_KINDS.includes(binding.kind)) {
      output.push(entryFor(binding, "invalid-kind", "kind is not an allow-listed attachment reference"));
      continue;
    }
    if (!ref) {
      output.push(entryFor(binding, "invalid-ref", "attachmentRef is missing"));
      continue;
    }
    if (!hash) {
      output.push(entryFor(binding, "missing-hash", "contentHash is missing"));
      continue;
    }
    if (!SHA256_HEX.test(hash)) {
      output.push(entryFor(binding, "invalid-hash", "contentHash is not a SHA-256 hex digest"));
      continue;
    }
    if (!owner) {
      output.push(entryFor(binding, "missing-owner", "owner is missing"));
      continue;
    }
    if (ttl === null) {
      output.push(entryFor(binding, "expired", "TTL is missing or invalid"));
      continue;
    }
    if (ttl <= now) {
      output.push(entryFor(binding, "expired", "TTL has expired"));
      continue;
    }

    const normalizedHash = hash.toLowerCase();
    const previous = seen.get(ref);
    if (!previous) {
      const entry = entryFor(binding, "recovered", "binding is valid");
      seen.set(ref, { hash: normalizedHash, entry });
      output.push(entry);
      continue;
    }
    if (previous.hash !== normalizedHash) {
      output.push(entryFor(binding, "conflict", "attachmentRef is bound to a different content hash"));
      continue;
    }
    // Same reference and hash is an idempotent duplicate. It is not emitted a
    // second time, and recovery never replays an attachment's side effect.
  }

  const entries = output.slice().sort((a, b) => {
    const refOrder = a.attachmentRef.localeCompare(b.attachmentRef);
    if (refOrder !== 0) return refOrder;
    const hashOrder = (a.contentHash || "").localeCompare(b.contentHash || "");
    if (hashOrder !== 0) return hashOrder;
    return a.state.localeCompare(b.state);
  });
  const recovered = entries.filter((entry) => entry.state === "recovered");
  const body = { entries, recovered };
  return { ...body, digest: computeCheckpointAttachmentRecoveryDigest(body) };
}

/** Compatibility aliases for callers that use the shorter task terminology. */
export const recoverAttachmentBindings = recoverCheckpointAttachmentBindings;

export function isCheckpointAttachmentKind(value: unknown): value is CheckpointAttachmentKind {
  return typeof value === "string" && (CHECKPOINT_ATTACHMENT_KINDS as readonly string[]).includes(value);
}

export function isValidCheckpointContentHash(value: unknown): value is string {
  return typeof value === "string" && SHA256_HEX.test(value);
}

/** Validate an untrusted JSON-like object before using it as a binding. */
export function parseCheckpointAttachmentBinding(value: unknown): CheckpointAttachmentBinding | null {
  if (!isRecord(value)) return null;
  const kind = value.kind;
  const attachmentRef = asNonEmptyString(value.attachmentRef);
  const contentHash = asNonEmptyString(value.contentHash);
  const owner = asNonEmptyString(value.owner);
  const ttl = asTtl(value.ttl);
  if (!isCheckpointAttachmentKind(kind) || !attachmentRef || !contentHash || !owner || ttl === null) return null;
  return { kind, attachmentRef, contentHash, owner, ttl };
}

